    agregar("G31-L1-02", CLASE_31, "L1", "Hola, cuando freno despacito antes de parar el pedal empieza a temblar como loco.", "WHATSAPP", "baja_velocidad", "pedal_tiembla_baja_velocidad", "", "", "SI", "NO", "", "L1 falso disparo de ABS en seco.")
